<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue';import{Head,Link,router,useForm}from'@inertiajs/vue3';import{computed,ref}from'vue';
const props=defineProps<{assignments:any[];questions:any[];exams:any[];attempts:any[];components:any[];can_manage:boolean;is_student:boolean}>();const showQ=ref(false),showE=ref(false);
const q=useForm({teaching_assignment_id:'',type:'multiple_choice',prompt:'',options:['',''],correct_answer:'',explanation:'',points:1});
const e=useForm({teaching_assignment_id:props.assignments[0]?.id??'',assessment_component_id:'',title:'',instructions:'',starts_at:'',ends_at:'',duration_minutes:60,randomize_questions:true,randomize_options:true,max_violations:3,question_ids:[] as number[]});
const attemptsByExam=computed(()=>new Map(props.attempts.map(a=>[a.exam_id,a])));const submitQ=()=>q.post('/ujian/soal',{onSuccess:()=>{showQ.value=false;q.reset()}});const submitE=()=>e.post('/ujian',{onSuccess:()=>showE.value=false});
</script>
<template><Head title="Ujian CBT"/><AppLayout><main class="view space-y-6"><section class="hero-card exam-hero"><div><p class="eyebrow">Computer based test</p><h1>Ujian & bank soal</h1><p>Kelola soal, jadwal, attempt, koreksi, dan hasil ujian secara terukur.</p></div><div v-if="can_manage" class="actions"><button class="secondary-button" @click="showQ=true">+ Bank soal</button><button class="primary-button" @click="showE=true">+ Buat ujian</button></div></section><section v-if="can_manage" class="grade-summary"><div><span>Bank soal</span><strong>{{ questions.length }}</strong></div><div><span>Ujian</span><strong>{{ exams.length }}</strong></div><div><span>Terbit</span><strong>{{ exams.filter(x=>x.status==='published').length }}</strong></div><div><span>Attempt</span><strong>{{ exams.reduce((n,x)=>n+x.attempts_count,0) }}</strong></div></section><section class="panel exam-list"><article v-for="x in exams" :key="x.id"><div><p class="eyebrow">{{ x.status }} · {{ x.items_count }} soal</p><h2>{{ x.title }}</h2><p>{{ new Date(x.starts_at).toLocaleString('id-ID') }} — {{ new Date(x.ends_at).toLocaleString('id-ID') }} · {{ x.duration_minutes }} menit</p></div><div class="actions"><button v-if="can_manage&&x.status==='draft'" class="primary-button" @click="router.post(`/ujian/${x.id}/terbitkan`)">Terbitkan</button><Link v-if="can_manage" class="secondary-button" :href="`/ujian/${x.id}/hasil`">Hasil</Link><a v-if="can_manage" class="secondary-button" :href="`/ujian/${x.id}/hasil/export`">Export</a><Link v-if="is_student&&attemptsByExam.get(x.id)" class="primary-button" :href="`/ujian/attempt/${attemptsByExam.get(x.id).id}`">Lanjutkan</Link><button v-else-if="is_student" class="primary-button" @click="router.post(`/ujian/${x.id}/mulai`)">Mulai</button></div></article><p v-if="!exams.length" class="empty-state">Belum ada ujian yang tersedia.</p></section>
<div v-if="showQ" class="modal-backdrop" @click.self="showQ=false"><form class="modal-card" @submit.prevent="submitQ"><h2>Tambah soal</h2><label>Mapel (opsional)<select v-model="q.teaching_assignment_id"><option value="">Bank umum</option><option v-for="a in assignments" :key="a.id" :value="a.id">{{ a.subject?.name }} · {{ a.class_group?.name }}</option></select></label><label>Jenis<select v-model="q.type"><option value="multiple_choice">Pilihan ganda</option><option value="essay">Esai</option></select></label><label>Pertanyaan<textarea v-model="q.prompt" required rows="4"/></label><template v-if="q.type==='multiple_choice'"><label v-for="(_,i) in q.options" :key="i">Opsi {{ i+1 }}<input v-model="q.options[i]" required></label><button type="button" @click="q.options.push('')">+ Opsi</button><label>Kunci<select v-model="q.correct_answer" required><option v-for="o in q.options.filter(Boolean)" :key="o">{{ o }}</option></select></label></template><label>Poin<input v-model.number="q.points" type="number" min=".1" step=".1"></label><button class="primary-button">Simpan soal</button></form></div>
<div v-if="showE" class="modal-backdrop" @click.self="showE=false"><form class="modal-card" @submit.prevent="submitE"><h2>Buat ujian</h2><label>Kelas-mapel<select v-model="e.teaching_assignment_id"><option v-for="a in assignments" :key="a.id" :value="a.id">{{ a.subject?.name }} · {{ a.class_group?.name }}</option></select></label><label>Komponen nilai (opsional)<select v-model="e.assessment_component_id"><option value="">Tidak disinkronkan</option><option v-for="c in components.filter(x=>!x.teaching_assignment_id||String(x.teaching_assignment_id)===String(e.teaching_assignment_id))" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>Judul<input v-model="e.title" required></label><div class="grid"><label>Mulai<input v-model="e.starts_at" type="datetime-local" required></label><label>Selesai<input v-model="e.ends_at" type="datetime-local" required></label><label>Durasi<input v-model.number="e.duration_minutes" type="number"></label><label>Batas pelanggaran<input v-model.number="e.max_violations" type="number"></label></div><fieldset><legend>Pilih soal</legend><label v-for="item in questions" :key="item.id" class="check"><input v-model="e.question_ids" type="checkbox" :value="item.id">{{ item.prompt }}</label></fieldset><label class="check"><input v-model="e.randomize_questions" type="checkbox"> Acak soal</label><label class="check"><input v-model="e.randomize_options" type="checkbox"> Acak opsi</label><button class="primary-button">Simpan draf</button></form></div></main></AppLayout></template>
<style scoped>.exam-hero,.actions{display:flex;align-items:center;justify-content:space-between;gap:.7rem}.exam-list{display:grid;gap:.7rem;padding:1rem}.exam-list article{display:flex;justify-content:space-between;gap:1rem;padding:1rem;border:1px solid #e2e8f0;border-radius:.8rem}.exam-list h2{font-weight:800}.modal-backdrop{position:fixed;inset:0;z-index:80;display:grid;place-items:center;background:#0f172a88}.modal-card{width:min(680px,94vw);max-height:90vh;overflow:auto;display:grid;gap:.8rem;padding:1.25rem;background:white;border-radius:1rem}.modal-card label{display:grid;gap:.3rem}.modal-card input:not([type=checkbox]),.modal-card select,.modal-card textarea{border:1px solid #cbd5e1;border-radius:.6rem;padding:.6rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}.check{display:flex!important;align-items:center;gap:.5rem}.modal-card fieldset{display:grid;gap:.4rem;max-height:180px;overflow:auto}@media(max-width:760px){.exam-hero,.exam-list article{align-items:stretch;flex-direction:column}.grid{grid-template-columns:1fr}}</style>
